    const key=`UNIDAD: ${unit}`,conversation=source==='cloud'&&meta?.snapshotId?threadBlock(module,meta.snapshotId,adminRegionLabel(),key):'';
    $('r34DetailBody').innerHTML=`<div class="rcv34-kpis"><article class="rcv34-kpi"><small>REAL</small><strong>${money(t.real)}</strong></article><article class="rcv34-kpi"><small>PRESUPUESTO</small><strong>${money(t.budget)}</strong></article><article class="rcv34-kpi"><small>VARIACIÓN</small><strong>${money(t.diff)}</strong></article><article class="rcv34-kpi"><small>ESTADO</small><strong>${sema(t.st)}</strong></article></div><article class="rcv34-card"><h3>3. Información de la jerarquía seleccionada</h3><div class="rcv34-subhier-grid">${acctCards}</div></article><article class="rcv34-card"><div class="rcv41-detail-head"><div><h3>4. Detalle completo de la jerarquía</h3><p id="r41DetailCount">${rows.length.toLocaleString()} movimientos mostrados de ${rows.length.toLocaleString()}.</p></div><div class="rcv42-detail-tools"><div class="rcv41-detail-filters" role="group" aria-label="Filtrar movimientos por estado"><button class="rcv41-state-btn active" data-r41-state="all">Todos <b>${rows.length.toLocaleString()}</b></button><button class="rcv41-state-btn red" data-r41-state="red">Rojos <b>${redRows.toLocaleString()}</b></button><button class="rcv41-state-btn green" data-r41-state="green">Verdes <b>${greenRows.toLocaleString()}</b></button></div><input id="r42DetailSearch" class="rcv42-search" placeholder="Buscar cuenta, concepto, sublibro…"></div></div><div class="rcv34-table-wrap"><table class="rcv34-table"><thead><tr><th>Jerarquía contable</th><th>Cuenta / concepto</th><th>Jerarquía Sublibro</th><th>Unidad de negocio JDE</th><th>Periodo</th><th>Real</th><th>Presupuesto</th><th>Estado</th></tr></thead><tbody id="r41DetailRows">${makeRows(rows)}</tbody></table></div><div id="r41DetailEmpty" class="rcv41-detail-empty rcv34-hidden">No hay movimientos con el estado seleccionado.</div></article>${plan}${conversation}`;
    $('r34Detail').classList.add('open');
